package cn.zhuatech.cashflowai.controller; import cn.zhuatech.cashflowai.common.ApiResponse; import cn.zhuatech.cashflowai.dto.CashflowAiDto.*; import cn.zhuatech.cashflowai.service.CashflowAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final CashflowAiService service;public OperationsAdminController(CashflowAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
